const ELEMENT_PROP_KEYS = new Set(["theme","eyebrow","tagline","caption","direction","angle","duration","hold","accent","tint","fontFamily","ink","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  eyebrow: "Introducing",
  tagline: "Motion for the films you launch with.",
  caption: "Copy it in. Change anything.",
  direction: "right",
  angle: 22,
  duration: 12,
  hold: 30,
  accent: "#3B5BFD",
  fontFamily: "Onest",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type FlashSweepElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FlashSweepBase>;

const FlashSweepInner = forwardRef<
  HTMLDivElement,
  FlashSweepElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FlashSweep>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FlashSweepBase
          {...(componentProps as unknown as ComponentProps<typeof FlashSweepBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FlashSweep = Interactive.withSchema({
  Component: FlashSweepInner,
  componentName: "<FlashSweep>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
